sp_widget.client_script:
function ($scope, $rootScope, spUtil, $timeout) {
  // ========================
  // ESTADO
  // ========================
  $scope.anoSelecionado = "";
  $scope.latestYear = null;
  $scope.dadosVisiveis = null;
  $scope.isFading = false;

  var chartInstance = null;
  var currentAngle = 0;
  var animationFrameId = null;
  var resizeTimer = null;
  var offAnoListener = null;

  // ========================
  // CORES — conforme legenda oficial
  // ========================
  var COLOR_GREEN  = "#8BC34A"; // 0–54%
  var COLOR_YELLOW = "#FFEB3B"; // 54–57%
  var COLOR_ORANGE = "#FF9800"; // 57–60%
  var COLOR_RED_LT = "#F44336"; // 60% (tick + marcador)
  var COLOR_RED_DK = "#8C0C03"; // 60–100%

  // ========================
  // UTIL
  // ========================
  function clampPct(p) { return Math.max(0, Math.min(p, 100)); }
  function mapValueToAngle(percent) { return (clampPct(percent) / 100) * Math.PI; }
  function truncate2(x) { if (typeof x !== 'number') return x; return (Math.floor(x * 100) / 100).toFixed(2); }

  function loadChartJs() {
    return new Promise(function (resolve) {
      if (window.Chart) return resolve();
      var s = document.createElement("script");
      s.src = "https://cdn.jsdelivr.net/npm/chart.js";
      s.onload = resolve;
      document.head.appendChild(s);
    });
  }

  // ========================
  // CHART.JS — 5 FATIAS exatas
  // ========================
  function buildDataset() {
    return {
      data: [54, 3, 3, 0.2, 39.8], // 0–54 / 54–57 / 57–60 / 60 / >60
      backgroundColor: [
        COLOR_GREEN,
        COLOR_YELLOW,
        COLOR_ORANGE,
        COLOR_RED_LT,
        COLOR_RED_DK
      ],
      borderWidth: 0,
      circumference: 180,
      rotation: 270,
      cutout: "70%"
    };
  }

  function renderGauge(percentual) {
    var canvas = document.getElementById("gaugeChart");
    if (!canvas) return;
    var ctx = canvas.getContext("2d");
    if (!ctx) return;

    Chart.defaults.elements.arc.borderWidth = 0;
    Chart.defaults.elements.arc.borderColor = "rgba(0,0,0,0)";
    Chart.defaults.plugins.legend.display = false;

    if (chartInstance) { try { chartInstance.destroy(); } catch(e){} chartInstance = null; }

    chartInstance = new Chart(ctx, {
      type: "doughnut",
      data: {
        labels: ["Verde", "Amarelo", "Laranja", "Vermelho Claro", "Vermelho Escuro"],
        datasets: [ buildDataset() ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: { duration: 0 },
        elements: { arc: { borderWidth: 0 } },
        plugins: { legend: { display: false }, tooltip: { enabled: false } }
      }
    });

    syncPointerCanvasSize();
    animatePointer(mapValueToAngle(percentual || 0), percentual || 0);
  }

  // ========================
  // PONTEIRO (canvas separado)
  // ========================
  function syncPointerCanvasSize() {
    var chartCanvas = document.getElementById("gaugeChart");
    var pointerCanvas = document.getElementById("gaugePointer");
    if (!chartCanvas || !pointerCanvas) return;

    var dpr = window.devicePixelRatio || 1;
    var cssW = chartCanvas.offsetWidth;
    var cssH = chartCanvas.offsetHeight;

    pointerCanvas.width  = Math.max(1, Math.floor(cssW * dpr));
    pointerCanvas.height = Math.max(1, Math.floor(cssH * dpr));
    pointerCanvas.style.width  = cssW + "px";
    pointerCanvas.style.height = cssH + "px";

    var ctx = pointerCanvas.getContext("2d");
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }

  // Tick visual de 60%
  function drawLimitTickAt(percent, color) {
    var canvas = document.getElementById("gaugePointer");
    if (!canvas) return;
    var ctx = canvas.getContext("2d");
    var W = parseFloat(canvas.style.width) || canvas.width;
    var H = parseFloat(canvas.style.height) || canvas.height;
    var cx = W / 2;
    var cy = H;

    var outerR = Math.min(W, H * 2) / 2 - 10;
    var innerR = outerR * 0.70;
    var midR   = innerR + (outerR - innerR) * 0.5;

    var a = mapValueToAngle(percent);
    var delta = (3 * Math.PI) / 180;

    var start = Math.PI - (a + delta);
    var end   = Math.PI - (a - delta);

    ctx.beginPath();
    ctx.arc(cx, cy, midR, start, end, false);
    ctx.strokeStyle = color;
    ctx.lineWidth = Math.max(4, Math.floor(H * 0.02));
    ctx.lineCap = "round";
    ctx.stroke();
  }

  function drawPointerAtAngle(angle, percentual) {
    var canvas = document.getElementById("gaugePointer");
    if (!canvas) return;
    var ctx = canvas.getContext("2d");
    var W = parseFloat(canvas.style.width) || canvas.width;
    var H = parseFloat(canvas.style.height) || canvas.height;

    ctx.clearRect(0, 0, W, H);

    var cx = W / 2;
    var cy = H;
    var length = H * 0.75;

    var theta = Math.PI - angle;
    var tipX = cx + length * Math.cos(theta);
    var tipY = cy - length * Math.sin(theta);

    var pointerColor = "#333";

    // haste
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(tipX, tipY);
    ctx.strokeStyle = pointerColor;
    ctx.lineWidth = 3;
    ctx.stroke();

    // ponta
    var ahLen = H * 0.08;
    var ahWid = H * 0.05;
    var ux = Math.cos(theta), uy = -Math.sin(theta);
    var baseX = tipX - ahLen * ux, baseY = tipY - ahLen * uy;
    var leftX  = baseX + (ahWid / 2) * uy, leftY  = baseY + (ahWid / 2) * -ux;
    var rightX = baseX - (ahWid / 2) * uy, rightY = baseY - (ahWid / 2) * -ux;

    ctx.beginPath();
    ctx.moveTo(tipX, tipY);
    ctx.lineTo(leftX, leftY);
    ctx.lineTo(rightX, rightY);
    ctx.closePath();
    ctx.fillStyle = pointerColor;
    ctx.fill();

    // pivô
    ctx.beginPath();
    ctx.arc(cx, cy, 5, 0, Math.PI * 2);
    ctx.fillStyle = pointerColor;
    ctx.fill();

    // label
    ctx.font = "bold 18px Arial";
    ctx.fillStyle = "#333";
    ctx.textAlign = "center";
    ctx.textBaseline = "bottom";
    ctx.fillText(truncate2(percentual) + "%", tipX, tipY - H * 0.05);

    // tick vermelho-claro (60%)
    drawLimitTickAt(60, COLOR_RED_LT);
  }

  function animatePointer(toAngle, percentual) {
    if (animationFrameId) cancelAnimationFrame(animationFrameId);
    var duration = 500;
    var startAngle = currentAngle;
    var delta = toAngle - startAngle;
    var startTime = performance.now();

    function step(now) {
      var t = Math.min((now - startTime) / duration, 1);
      currentAngle = startAngle + delta * (1 - Math.pow(1 - t, 3));
      drawPointerAtAngle(currentAngle, percentual);
      if (t < 1) animationFrameId = requestAnimationFrame(step);
    }
    animationFrameId = requestAnimationFrame(step);
  }

  // ========================
  // DADOS (ServiceNow)
  // ========================
  var ultimoAnoCache = null;

  function buscarUltimoAnoDisponivel() {
    if (ultimoAnoCache) return Promise.resolve(ultimoAnoCache);
    return spUtil.get("widget_limite_com_despesas_semidonut", { filtro_ano: "" })
      .then(function(resp){
        var dados = (resp.data && resp.data.dados) || [];
        if (!dados.length) return null;
        var anos = Array.from(new Set(dados.map(i => i.ano))).sort();
        ultimoAnoCache = anos[anos.length - 1] || null;
        return ultimoAnoCache;
      })
      .catch(err => { console.error("Erro ao buscar anos disponíveis:", err); return null; });
  }

  function carregarDadosDoAno(ano) {
    return spUtil.get("widget_limite_com_despesas_semidonut", { filtro_ano: ano })
      .then(function(resp){
        var dados = (resp.data && resp.data.dados) || [];
        if (!dados.length) {
          $scope.dadosVisiveis = null;
          $scope.latestYear = null;
          limparCanvas();
          return null;
        }
        $scope.dadosVisiveis = dados[0];
        $scope.latestYear = ano;

        var p = ($scope.dadosVisiveis.comprometimento != null) ? $scope.dadosVisiveis.comprometimento : 0;
        renderGauge(p);
        return p;
      })
      .catch(err => { console.error("Erro ao buscar dados:", err); limparCanvas(); return null; })
      .finally(() => { $scope.isFading = false; });
  }

  function atualizarDados(ano) {
    $scope.isFading = true;
    if (!ano) {
      buscarUltimoAnoDisponivel().then(function(ultimo){
        if (ultimo) {
          $scope.anoSelecionado = String(ultimo);
          carregarDadosDoAno(ultimo);
        } else {
          $scope.latestYear = null; $scope.dadosVisiveis = null;
          limparCanvas(); $scope.isFading = false;
        }
      });
      return;
    }
    carregarDadosDoAno(ano);
  }

  function limparCanvas() {
    var c = document.getElementById("gaugePointer");
    if (c) {
      var ctx = c.getContext("2d");
      var w = parseFloat(c.style.width) || c.width;
      var h = parseFloat(c.style.height) || c.height;
      ctx.clearRect(0, 0, w, h);
    }
    if (chartInstance) { try { chartInstance.destroy(); } catch(e){} chartInstance = null; }
  }

  // ========================
  // EVENTOS
  // ========================
  $scope.anoChanged = function () {
    var y = parseInt($scope.anoSelecionado, 10);
    var thisYear = new Date().getFullYear();
    if ($scope.anoSelecionado && (y < 2000 || y > thisYear)) {
      console.warn("Ano fora do intervalo permitido.");
      return;
    }
    $rootScope.$broadcast("anoSelecionado", $scope.anoSelecionado);
  };

  function onResize() {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(function () {
      if ($scope.dadosVisiveis && $scope.dadosVisiveis.comprometimento != null) {
        renderGauge($scope.dadosVisiveis.comprometimento);
      }
    }, 150);
  }

  // ========================
  // BOOTSTRAP
  // ========================
  loadChartJs().then(function () {
    buscarUltimoAnoDisponivel().then(function(ultimoAno){
      if (ultimoAno) {
        $scope.anoSelecionado = String(ultimoAno);
        $rootScope.$broadcast("anoSelecionado", $scope.anoSelecionado);
      }
    });

    offAnoListener = $rootScope.$on("anoSelecionado", function (evt, ano) {
      $scope.anoSelecionado = ano;
      atualizarDados(ano);
    });

    window.addEventListener("resize", onResize);
  });

  // ========================
  // CLEANUP
  // ========================
  $scope.$on("$destroy", function(){
    if (offAnoListener) offAnoListener();
    window.removeEventListener("resize", onResize);
    if (animationFrameId) cancelAnimationFrame(animationFrameId);
    limparCanvas();
  });
}

sp_widget.css:
/* =========================
   Base & painel
========================= */
:root{
  --bg:#fff;
  --ink:#202124;
  --muted:#6b7280;
  --line:#eceff1;
  --card:#fafafa;
  --shadow:0 1px 2px rgba(0,0,0,.04);
  --shadow-lg:0 6px 18px rgba(0,0,0,.08);
}

.report-widget{
  background:var(--bg);
  border-radius:14px;
  box-shadow:0 2px 6px rgba(0,0,0,.06);
  overflow:hidden;
  font-family:'Roboto Flex',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;
  transition:.35s ease;
}

.report-widget.fade-out{opacity:.35;filter:grayscale(.25)}
.report-widget.panel.empty .panel-body{padding:28px;text-align:center}

.panel-heading{
  background:#e5e7eb;
  border-bottom:1px solid #d9dde3;
  padding:12px 16px;
}
.panel-title{
  margin:0;
  font-weight:700;
  font-size:18px;
  color:var(--ink);
  text-align:center;
}
.panel-body{padding:16px 16px 18px}

/* =========================
   Gauge area
========================= */
.chart-wrap{display:flex;justify-content:center}
.chart-container{
  position:relative;
  width:100%;
  max-width:860px;
  height:240px;               /* altura confortável */
  margin:2px auto 22px;
}
.pointer-canvas{
  position:absolute;top:0;left:0;display:block;width:100%;height:100%;
}
canvas{display:block;margin:0 auto;max-width:100%;height:auto}

/* =========================
   Escala (0% e 100%)
========================= */
.gauge-scale {
  position: absolute;
  left: 0;
  bottom: 0; /* alinhado exatamente com a base do semidonut */
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  pointer-events: none;
  transform: translateY(50%); /* empurra levemente para baixo do arco */
}

.scale-min,
.scale-max {
  font-weight: 700;
  color: #2b2f33;
  background: #fff;
  border-radius: 6px;
  padding: 2px 6px;
  box-shadow: 0 1px 2px rgba(0, 0, 0, .06);
  font-size: 13px;
}

/* =========================
   Legend as cards
========================= */
.legend{
  width:100%;
  max-width:920px;
  margin:0 auto 6px;
  display:flex;
  flex-direction:column;      /* 1 por linha */
  gap:4px;                    /* pouco espaço entre itens */
}
.legend-item{
  display:grid;
  grid-template-columns:22px 1fr;
  align-items:flex-start;
  gap:5px;
  border:1px solid var(--line);
  background:var(--card);
  border-radius:12px;
  padding:10px 12px;
  box-shadow:var(--shadow);
}
.legend-item:hover{box-shadow:var(--shadow-lg);background:#fff}

.legend-dot{
  width:18px;height:18px;border-radius:6px;
  background:var(--dot, #ccc);
  box-shadow:inset 0 0 0 1px rgba(0,0,0,.06);
}
.legend-text h4{
  margin:0 0 3px 0;
  font-weight:800;
  color:var(--ink);
  font-size:15px;
  line-height:1.25;
}
.legend-text p{
  margin:0;
  color:var(--muted);
  font-size:13px;
  line-height:1.45;
}

/* =========================
   Resume (ano + valor)
========================= */
.resume{
  text-align:center;
  margin-top:18px;
  padding:12px 14px;
  background:#f6f7f9;
  border:1px solid var(--line);
  border-radius:12px;
  font-size:16px;
  font-weight:600;
}

/* =========================
   Empty state
========================= */
.nodata{margin:0;font-size:15px;color:var(--muted)}

/* =========================
   Responsivo
========================= */
@media (max-width:1024px){
  .chart-container{height:210px;margin-bottom:18px}
  .legend-text h4{font-size:14.5px}
  .legend-text p{font-size:12.5px}
  .resume{font-size:15px}
}
@media (max-width:768px){
  .chart-container{height:190px}
  .legend{gap:7px}
  .legend-item{padding:9px 11px}
  .legend-text h4{font-size:14px}
  .legend-text p{
    font-size:12px;
    display:-webkit-box;
    -webkit-line-clamp:2;     /* corta descrições longas no mobile */
    -webkit-box-orient:vertical;
    overflow:hidden;
  }
}
@media (max-width:480px){
  .chart-container{height:170px}
  .scale-min,.scale-max{font-size:12px}
  .legend-dot{width:16px;height:16px;border-radius:5px}
  .legend-text h4{font-size:13.5px}
  .legend-text p{font-size:11.5px}
  .resume{font-size:14.5px;padding:10px 12px}
}

sp_widget.script:
(function() {
  var anoFiltrado = (typeof input !== 'undefined' && input.filtro_ano) ? input.filtro_ano : '';
  var gr = new GlideRecord('x_sded9_portal_t_0_u_despesa_pessoal');

  if (anoFiltrado) {
    gr.addQuery('u_ano', anoFiltrado);
  }

  gr.orderByDesc('u_ano');
  gr.query();

  var dados = [];
  while (gr.next()) {
    dados.push({
      ano: gr.getValue('u_ano'),
      comprometimento: parseFloat(gr.getValue('u_comprometimento_rcl')) || 0
    });
  }

	//gs.addInfoMessage(JSON.stringify(dados));

  data.dados = dados;
})();
